def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""

    if not s:
        raise ValueError("Version string cannot be empty")

    parts = s.split('.')
    version_parts = []

    for part in parts:
        if not part:
            raise ValueError("Version part cannot be empty")

        if '-' in part:
            # Handle version with pre-release
            version_part = tuple(map(int, part.split('-')[0].split('.')))
        else:
            # Handle version without pre-release
            version_part = tuple(map(int, part.split('.')))

        version_parts.append(version_part)

    return tuple(version_parts[0] if len(version_parts) == 1 else tuple(map(int, zip(*version_parts))))

