def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """

    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)

            if k not in cache:
                with lock:
                    if k not in cache:
                        result = func(*args, **kwargs)
                        cache[k] = result
            else:
                result = cache[k]

            return result

        return wrapper

    return decorator

