def _validate_labels(labels):
    errors = []
    for key, value in labels.items():
        if not isinstance(value, (str, bytes)):
            errors.append({"key": key, "value": "expected string or bytes-like object"})
        elif '$$' in key and not re.match(r'[^_][^_]*$', key):
            errors.append({"key": key, "value": "Label key '$$' does not match the regex [^_][^_]*$"})
        else:
            for regex in re.findall(r"\${([^}]*)}", key):
                if not re.match(regex, key):
                    errors.append({"key": key, "value": f"Label key '$${regex}' does not match the regex '{regex}'"})
    if errors:
        raise ValidationError(errors)

