def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    filename : str
        filename
    file_folder : str
        file folder

    Returns
    -------
    dict
    """
    if filename.endswith('.png') or filename.endswith('.jpg') or filename.endswith('.gif'):
        return {'type': 'asset', 'path': os.path.join(file_folder, filename)}
    elif filename.endswith('.mp4') or filename.endswith('.avi') or filename.endswith('.mov'):
        return {'type': 'rendition', 'path': os.path.join(file_folder, filename)}
    else:
        return {'type': 'unknown', 'path': os.path.join(file_folder, filename)}

