def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0
    warning_count = 0

    root = self

    while root:
        num_objects += 1

        # Step 1: Check for valid children
        if not validate_objects:
            continue

        for child in root.children:
            if not child.is_valid():
                if show_warnings:
                    print(f"Warning: Invalid child {child} on level {root.level + 1}")
                warning_count += 1
            else:
                good_objects += 1

        # Step 2: Check for valid digest
        if check_digests:
            actual_digest = self.calculate_digest()
            expected_digest = root.get_expected_digest()

            if actual_digest != expected_digest:
                if show_warnings:
                    print(f"Warning: Invalid digest on level {root.level + 1}")
                warning_count += 1
            else:
                good_objects += 1

        root = root.parent

    return num_objects, good_objects, warning_count

