def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        return '-' + int_to_string(-number, alphabet)

    result = ['/' if padding is not None and i == padding else '' for i in range(len(alphabet))]

    for i in range(len(str(number))):
        if number > 0:
            div, mod = divmod(number, alphabet)
            result[i] = alphabet[mod]
            number = div

    if padding is not None and len(result) < padding:
        result += ['/'.join(result[i:padding-len(result)]) for i in range(padding-len(result))]

    return ''.join(result)

