def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """

        parser_dict = deepcopy(self.specs)
        if not parser_dict:
            return

        for group_name, include_info in parser_dict.items():
            try:
                group_path = self.specs_path + include_info[0]
                if not os.path.exists(group_path):
                    raise ValueError(f"Spec file {group_path} does not exist.")
                group_dict = json.load(open(group_path))

                for key, value in group_dict.items():
                    if key in parser_dict:
                        if isinstance(parser_dict[key], list):
                            parser_dict[key].append(value)
                        else:
                            parser_dict[key] = [parser_dict[key], value]
                    else:
                        parser_dict[key] = value
            except Exception as e:
                logging.error(f"Error resolving include dict for group {group_name}: {e}")

        self.specs = parser_dict

